using System;
using System.Collections.Generic;
using StandaloneCompiler;

/// <summary>
/// Test program to verify that Association literals are properly generated by the compiler
/// and can be parsed by the interpreter.
/// </summary>
class TestAssociationHandling
{
    static void Main()
    {
        Console.WriteLine("=== Testing Association Literal Handling ===\n");
        
        // Test 1: Simple global variable access
        TestGlobalVariable();
        
        // Test 2: Class variable access
        TestClassVariable();
        
        // Test 3: Pool variable access
        TestPoolVariable();
        
        Console.WriteLine("\n=== All Association Tests Complete ===");
    }
    
    static void TestGlobalVariable()
    {
        Console.WriteLine("Test 1: Global Variable Access (Object)");
        Console.WriteLine("---------------------------------------");
        
        var compiler = new BytecodeCompiler();
        
        // Method that accesses global variable Object
        var methodSource = "testObject\n\t^Object!";
        var instanceVars = new List<string>();
        var result = compiler.CompileMethod(methodSource, instanceVars);
        
        Console.WriteLine($"Method: {methodSource.Replace("\n", " ").Replace("\t", "").Replace("!", "")}");
        Console.WriteLine($"Bytecodes: [{string.Join(", ", result.Bytecode)}]");
        Console.WriteLine($"Literals ({result.Literals.Length}):");
        
        for (int i = 0; i < result.Literals.Length; i++)
        {
            var lit = result.Literals[i];
            if (lit is Association assoc)
            {
                Console.WriteLine($"  [{i}] = Association(key: #{assoc.Key}, value: {assoc.Value ?? "null"})");
                
                // Verify this creates the expected JSON representation
                var jsonRep = $"Association(key: #{assoc.Key}, value: null)";
                Console.WriteLine($"  JSON representation: {jsonRep}");
            }
            else if (lit is Symbol sym)
            {
                Console.WriteLine($"  [{i}] = Symbol(#{sym.Value})");
            }
            else
            {
                Console.WriteLine($"  [{i}] = {lit?.GetType().Name ?? "null"}");
            }
        }
        
        // Check bytecode is PushLiteralVariable
        if (result.Bytecode.Length >= 1 && result.Bytecode[0] >= 72 && result.Bytecode[0] <= 79)
        {
            Console.WriteLine("✓ Correctly uses PushLiteralVariable for global 'Object'");
        }
        else
        {
            Console.WriteLine("✗ Should use PushLiteralVariable for global 'Object'");
        }
        Console.WriteLine();
    }
    
    static void TestClassVariable()
    {
        Console.WriteLine("Test 2: Class Variable Access");
        Console.WriteLine("-----------------------------");
        
        var compiler = new BytecodeCompiler();
        var instanceVars = new List<string>();
        var classVars = new Dictionary<string, object> 
        { 
            ["Counter"] = new object()
        };
        
        var methodSource = "getCounter\n\t^Counter!";
        var result = compiler.CompileMethod(methodSource, instanceVars, classVars);
        
        Console.WriteLine($"Method: {methodSource.Replace("\n", " ").Replace("\t", "").Replace("!", "")}");
        Console.WriteLine($"Bytecodes: [{string.Join(", ", result.Bytecode)}]");
        Console.WriteLine($"Literals ({result.Literals.Length}):");
        
        for (int i = 0; i < result.Literals.Length; i++)
        {
            var lit = result.Literals[i];
            if (lit is Association assoc)
            {
                Console.WriteLine($"  [{i}] = Association(key: #{assoc.Key}, value: {assoc.Value ?? "null"})");
            }
            else if (lit is Symbol sym)
            {
                Console.WriteLine($"  [{i}] = Symbol(#{sym.Value})");
            }
            else
            {
                Console.WriteLine($"  [{i}] = {lit?.GetType().Name ?? "null"}");
            }
        }
        
        // Verify bytecode
        if (result.Bytecode.Length >= 1 && result.Bytecode[0] >= 72 && result.Bytecode[0] <= 79)
        {
            Console.WriteLine("✓ Correctly uses PushLiteralVariable for class variable");
        }
        else
        {
            Console.WriteLine("✗ Should use PushLiteralVariable for class variable");
        }
        Console.WriteLine();
    }
    
    static void TestPoolVariable()
    {
        Console.WriteLine("Test 3: Pool Variable Access");
        Console.WriteLine("----------------------------");
        
        var compiler = new BytecodeCompiler();
        var instanceVars = new List<string>();
        var poolVars = new Dictionary<string, object> 
        { 
            ["MaxInt"] = int.MaxValue
        };
        
        var methodSource = "getMaxInt\n\t^MaxInt!";
        var result = compiler.CompileMethod(methodSource, instanceVars, null, poolVars);
        
        Console.WriteLine($"Method: {methodSource.Replace("\n", " ").Replace("\t", "").Replace("!", "")}");
        Console.WriteLine($"Bytecodes: [{string.Join(", ", result.Bytecode)}]");
        Console.WriteLine($"Literals ({result.Literals.Length}):");
        
        for (int i = 0; i < result.Literals.Length; i++)
        {
            var lit = result.Literals[i];
            if (lit is Association assoc)
            {
                Console.WriteLine($"  [{i}] = Association(key: #{assoc.Key}, value: {assoc.Value ?? "null"})");
            }
            else if (lit is Symbol sym)
            {
                Console.WriteLine($"  [{i}] = Symbol(#{sym.Value})");
            }
            else
            {
                Console.WriteLine($"  [{i}] = {lit?.GetType().Name ?? "null"}");
            }
        }
        
        // Verify bytecode
        if (result.Bytecode.Length >= 1 && result.Bytecode[0] >= 72 && result.Bytecode[0] <= 79)
        {
            Console.WriteLine("✓ Correctly uses PushLiteralVariable for pool variable");
        }
        else
        {
            Console.WriteLine("✗ Should use PushLiteralVariable for pool variable");
        }
        Console.WriteLine();
    }
}